    // Les agendas en ligne, suite
    'agenda.portee_refusee' => 'The permission does not cover your calendar.',
    'agenda.portee_refusee_aide' => 'Connect again, and on the consent screen tick the calendar box — it is not ticked for you. Without it, the app can recognise you but sees no appointment.',
    'agenda.reconnecter' => 'Connect my account again',
    'agenda.partages_refuses' => 'If {nom} turns down the shared calendars, it is the permission.',
    'agenda.partages_refuses_aide.un' => 'You follow {n} calendar shared by someone else, and your permission predates the app being able to read them. Try it: depending on the account, it works. If the read is refused, authorise the app again — the button is below.',
    'agenda.partages_refuses_aide.plusieurs' => 'You follow {n} calendars shared by someone else, and your permission predates the app being able to read them. Try it: depending on the account, it works. If the read is refused, authorise the app again — the button is below.',
    'agenda.synchroniser_premiere' => 'Sync my calendar',
    'agenda.synchroniser' => 'Sync now',
    'agenda.auto_aide' => 'The sync runs <strong>on its own</strong> when you open the app, if the last one is more than five minutes old. The button is there so you need not wait, and so you can see the message if it is refused.',
    'agenda.vers_ici' => '<strong>From {nom} to here:</strong> the calendars ticked below, from last month to the year ahead, recurring series included — and “Mes Cours” itself, so that what you create there from {nom} reaches this side.',
    'agenda.modifs_ici' => '<strong>What you change or delete here</strong> changes in {nom} too, but <strong>only in the calendars you own</strong> — yours and “Mes Cours”. Coming from a calendar someone shared with you, the event can be edited here without changing anything on their side, and the next read restores their version. The app never writes into other people’s calendars of its own accord.',
    'agenda.exception' => '<strong>One exception, and you set it off:</strong> every event can name the calendar it goes to, including one belonging to someone who let you write in theirs. It is not a frozen copy — the event stays yours there, and what you do with it here follows it over.',
    'agenda.ici_vers' => '<strong>From here to {nom}:</strong> the deadlines of your unfinished tasks, and the events that name no other calendar, into <strong>“{dest}”</strong>{cree}. That is the only place it writes. A ticked task leaves the calendar, and an event deleted here disappears over there.',
    'agenda.cree_chez' => ', a calendar the app creates in {nom}',
    'agenda.destination_sur' => 'Change the destination calendar? What the app had put in the current one will be taken out, then put into the new one.',
    'agenda.destination' => 'The calendar that receives your events',
    'agenda.destination_appli' => 'Mes Cours — the app’s own calendar',
    'agenda.principal_suffixe' => ' — your main calendar',
    'agenda.destination_aide' => 'Only calendars of your own are offered. Naming one pours your events and your task deadlines into it: handy for a calendar others look at, provided that is really what you want them to see.',
    'agenda.changer_destination' => 'Change the destination',
    'agenda.retirer_importes_sur' => 'Remove from the calendar the events that came {de}? They stay in your own calendar.',
    'agenda.retirer_importes' => 'Remove the imported events',
    'agenda.retirer_envoi_sur' => 'Remove {de} what the app put there? Your events and your tasks stay here, untouched.',
    'agenda.retirer_envoi' => 'Remove my events {de}',
    'agenda.delier_sur' => 'Disconnect your {nom} account? The app will no longer reach your calendar, and the imported events will leave this one.',
    'agenda.delier' => 'Disconnect my account',
    'agenda.relier_titre' => 'Connect your account',
    'agenda.relier_aide' => 'Your {nom} appointments and classes will join the app’s calendar, and your events here will join yours.',
    'agenda.connecter' => 'Connect my {nom} account',
    'agenda.connecter_aide' => '{nom} will ask you to pick your account and allow access to your calendar, then bring you back here. You can disconnect whenever you like.',
    'agenda.calendriers_titre' => 'The calendars to read',
    'agenda.partage_ancien' => 'Your permission predates the app asking for calendars <strong>shared by someone else</strong>. It is not always needed — depending on the account, {nom} gives them without anything more. If one of them is refused, authorise again: nothing is lost, neither your link nor your events.',
    'agenda.reautoriser' => 'Authorise the app again',
    'agenda.aucun_calendrier' => 'The app has only read your main calendar. Ask {nom} for the full list to pick the others.',
    'agenda.calendrier' => 'Calendar',
    'agenda.principal' => 'main',
    'agenda.partage_par' => 'shared by {qui}',
    'agenda.quelquun' => 'someone',
    'agenda.enregistrer_choix' => 'Save my choice',
    'agenda.voir_calendriers' => 'See my calendars',
    'agenda.actualiser' => 'Refresh the list',
    'agenda.ce_que_voit' => 'What the app sees',
    'agenda.ce_que_voit_1' => 'Your calendar, and nothing else: it asks permission to read and write your events, your name and your address. Not your messages, not your files, not your contacts.',
    'agenda.ce_que_voit_2' => 'The permission obtained is kept in the app’s database. It is <strong>left out of exportable backups</strong>, and disconnecting your account erases it.',
    'agenda.pour_hebergeur' => 'For whoever hosts the app',
    // Les agendas : l’inscription chez le fournisseur
    'agenda.inscription_unique' => 'A single registration serves everyone. It is set in <code>config/parametres.php</code>, section <code>{section}</code>, which does not go to the repository.',
    'agenda.ms_1' => 'On <a href="https://entra.microsoft.com" target="_blank" rel="noopener">entra.microsoft.com</a>: <em>Applications</em> › <em>App registrations</em> › <em>New registration</em>.',
    'agenda.ms_2' => 'Supported account types: <em>Accounts in any organizational directory and personal Microsoft accounts</em>.',
    'agenda.ms_3' => 'Redirect URI — enter this one, word for word:',
    'agenda.ms_4' => 'Platform: <strong>Mobile and desktop applications</strong> when local, with no secret; <strong>Web</strong> once online, with a client secret.',
    'agenda.ms_5' => 'Copy the <strong>Application (client) ID</strong> into <code>outlook.client_id</code>.',
    'agenda.g_1' => 'On <a href="https://console.cloud.google.com" target="_blank" rel="noopener">console.cloud.google.com</a>: create a project, then enable <em>Google Calendar API</em>.',
    'agenda.g_2' => '<em>Data access</em>: add the scope <code>https://www.googleapis.com/auth/calendar</code>, and that one only.',
    'agenda.g_3' => '<em>Audience</em>: add your address under <em>Test users</em>, or publish the app — otherwise Google turns down even your own account.',
    'agenda.g_4' => '<em>Clients</em>: an OAuth client of type <strong>Web application</strong>, with this redirect address, word for word:',
    'agenda.g_5' => 'Copy the <strong>client ID</strong> and the <strong>secret</strong> into <code>google.client_id</code> and <code>google.secret</code> — Google wants both, even locally.',
    'agenda.g_test' => 'As long as the app stays “in testing” at Google, the permission expires after seven days and you must connect again. Publishing it — one button, no review, no wait — removes that limit; the warning screen stays until the review.',
    'agenda.en_ligne' => 'Online, also set <code>{section}.adresse_retour</code> explicitly: what a browser claims as its host is not to be taken at its word, and this address must match the one declared over there.',
