    'cpt.fuseau' => '🕑 Time zone',
    'cpt.fuseau_nouveau' => 'New time zone',
    'cpt.fuseau_aide' => 'Changing zone does not move what is already noted: a class at 8 stays at 8, simply read in the new time. That is what you want when moving house — less so when fixing a wrong setting, where the times must be redone by hand.',
