    'cpt.coupee_puce' => '⛔ Off',
    'cpt.transcription_aide' => 'When on, your browser writes what you say as you record, and your friends read the text under the voice message. Chrome and Edge send the sound to Google or Microsoft for that; Firefox cannot transcribe. When off, your voice messages go without text. Those already sent do not change.',
    'cpt.partages' => '🔗 What is shared with me',
