    'cpt.partages_choix_1' => 'It arrives as a card in our conversation, and in “Shared”',
    'cpt.partages_choix_2' => 'It only arrives in “Shared”, with a notification',
    'cpt.partages_aide' => 'Either way, the “Shared” tab counts what you have not seen yet, and the note that comes with a share is read there. A share made to a group always arrives in the group: the conversation belongs to all its members.',
    'cpt.mon_calendrier' => '📅 Share my calendar',
    'cpt.mon_calendrier_vide' => 'You have no friends yet to open your calendar to.',
    'cpt.mon_calendrier_aide' => 'Opened to a friend, your calendar shows in theirs, read only: all your events, today’s and the ones you will add. Only “My events” — not your Outlook and Google calendars, nor what others have shared with you.',
    'cpt.montre_le_sien' => '· shows you theirs',
