    'cpt.calendrier_amis_aide' => 'Choose, friend by friend, whether the events they share with you — one by one, or their whole calendar — show by default in your calendar and on your home page. They stay up to date there, and vanish if the share is withdrawn. Otherwise they wait for you in “Shared”.',
