    'aide.gemini.titre_page' => 'Get a Gemini API key',
    'aide.gemini.titre' => 'How to get a Gemini API key',
    'aide.gemini.bouton' => 'Step-by-step guide',
    'aide.gemini.intro' => 'An API key is a personal code that lets the app talk to Google’s artificial intelligence (Gemini) on your behalf. You create it for free in a few minutes; this guide walks you through it.',
    'aide.gemini.avant' => 'Before you start',
    'aide.gemini.avant_compte' => 'You need a Google account (a Gmail address, for example).',
    'aide.gemini.avant_age' => 'Google only allows people aged 18 or over to create keys and may ask you to verify your age.',
    'aide.gemini.avant_gratuit' => 'Basic use is free, within a limit of requests per minute and per day. No credit card is asked for.',
    'aide.gemini.vie_privee_titre' => 'Free tier and privacy',
    'aide.gemini.vie_privee' => 'With the free tier, Google may use the texts you send to improve its products. Do not put sensitive information in them (health, passwords, other people’s data…).',
    'aide.gemini.e1_titre' => 'Open Google AI Studio',
    'aide.gemini.e1' => 'Go to aistudio.google.com/apikey and sign in with your Google account if asked.',
    'aide.gemini.ouvrir' => 'Open Google AI Studio',
    'aide.gemini.e1_fig' => 'Diagram: a browser address bar showing aistudio.google.com/apikey.',
    'aide.gemini.e2_titre' => 'Accept the terms',
    'aide.gemini.e2' => 'The first time, Google shows its terms of service. Tick the acceptance box, then click “Continue”.',
    'aide.gemini.e2_fig' => 'Diagram: a terms-of-service window with a ticked box and a Continue button.',
    'aide.gemini.e3_titre' => 'Create the key',
    'aide.gemini.e3' => 'On the keys page (“API keys”), click the blue “Create API key” button.',
    'aide.gemini.e3_fig' => 'Diagram: the “API keys” page with the blue “Create API key” button.',
    'aide.gemini.e3_aide' => 'The button’s name may vary with your Google account’s language or a site update: look for the button that creates a key, or the “API keys” menu on the left.',
    'aide.gemini.e4_titre' => 'Choose a project',
    'aide.gemini.e4' => 'Google files each key in a “project”. Pick the default project, or “Create API key in new project”, then confirm with “Create API key”.',
    'aide.gemini.e4_fig' => 'Diagram: a “Create API key” window with a list of projects and a confirm button.',
    'aide.gemini.e4_aide' => 'If you are offered to create a project, its name hardly matters: it has no effect on the app.',
    'aide.gemini.e5_titre' => 'Copy the key',
    'aide.gemini.e5' => 'Your key appears in the list: a long string of letters and digits, often starting with “AIza”. Click the copy icon next to it, or select it entirely and copy it.',
    'aide.gemini.e5_fig' => 'Diagram: the list of keys with a copy icon to the right of the key.',
    'aide.gemini.secret_titre' => 'This key is secret',
    'aide.gemini.secret' => 'Share it with nobody and publish it nowhere: whoever has it can use your quota. If it leaks, delete it in Google AI Studio and create another one.',
    'aide.gemini.e6_titre' => 'Paste it into Mes Cours',
    'aide.gemini.e6' => 'In the app:',
    'aide.gemini.e6_fig' => 'Diagram: the “Gemini API key” card in My account with a field full of dots and the Save button.',
    'aide.gemini.e6_a' => 'Open “My account”, then the “Gemini API key” card, and click “Add a key”.',
    'aide.gemini.e6_b' => 'Paste the key in the field (it shows as dots, which is normal).',
    'aide.gemini.e6_c' => 'Click “Save”. The key is encrypted on the server; the screen then only shows its last characters.',
    'aide.gemini.vers_compte' => 'Go to “My account”',
    'aide.gemini.apres_titre' => 'All done?',
    'aide.gemini.apres' => 'Open the AI assistant and ask it a question: if it answers, the key works. AI summaries use the same key.',
    'aide.gemini.depannage' => 'If something goes wrong',
    'aide.gemini.q1' => '“That does not look like an API key”',
    'aide.gemini.r1' => 'The key was copied badly. Copy it again in full, with no space before or after, no quotation marks and no line break.',
    'aide.gemini.q2' => 'The assistant says the key is refused',
    'aide.gemini.r2' => 'The key may be incomplete, deleted or disabled. Create a new one in Google AI Studio and replace it in My account.',
    'aide.gemini.q3' => '“Limit reached” or “too many requests”',
    'aide.gemini.r3' => 'The free tier limits requests per minute and per day. Wait a few minutes, or until the next day if the daily limit is reached.',
    'aide.gemini.q4' => 'I cannot find the button in Google AI Studio',
    'aide.gemini.r4' => 'Their site changes. Look for “API keys” or “Get API key” in the menu, or reopen aistudio.google.com/apikey.',
    'aide.gemini.q5' => 'How do I delete my key?',
    'aide.gemini.r5' => 'In My account, click “Remove the key”: it is erased from the app. To invalidate it at Google, also delete it in Google AI Studio (trash icon next to the key).',
    'aide.gemini.schemas' => 'The diagrams are simplified drawings: Google’s real screen may differ slightly.',
    'apps.lien_icone' => 'Icon (optional: an emoji instead of the site’s own)',
    'apps.lien_enregistrer' => 'Save',
    'apps.lien_annuler' => 'Cancel',
    'apps.lien_supprimer' => 'Delete',
    'lia.err.nom' => 'Give the app a name (40 characters at most).',
    'lia.err.url' => 'Address refused: a website address is needed, like youtube.com or https://notebooklm.google.com.',
    'lia.err.logo' => 'The logo address must be an image or website address, starting with http or https.',
    'lia.err.icone' => 'The icon must be an emoji or a few letters (4 at most).',
    'lia.err.max' => 'You have reached the limit of {n} apps: delete one before adding another.',
    'js.apps.lien_echec' => 'Could not save the app — try again.',
    'js.apps.lien_supprimer_sur' => 'Remove “{nom}” from the menu?',
    'js.apps.lien_nouveau' => 'New app',
